<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-alt: #f8fafc;
      --text: #132238;
      --muted: #5a6b84;
      --border: #d7e0ea;
      --border-strong: #7c8ea8;
      --accent: #2563eb;
      --accent-soft: rgba(37, 99, 235, 0.08);
      --shadow: 0 18px 40px rgba(15, 23, 42, 0.08);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.1), transparent 32%),
        var(--bg);
    }

    .skip-link:not(:focus):not(:active) {
      position: absolute;
      width: 1px;
      height: 1px;
      margin: -1px;
      padding: 0;
      overflow: hidden;
      clip: rect(0 0 0 0);
      clip-path: inset(50%);
      border: 0;
      white-space: nowrap;
    }

    .skip-link {
      position: absolute;
      z-index: 2;
      top: 1rem;
      left: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      color: var(--text);
      box-shadow: var(--shadow);
      text-decoration: none;
      font-weight: 600;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 5rem 1.25rem 2rem;
    }

    .page-shell {
      width: min(100%, 720px);
    }

    .hero {
      margin-bottom: 1.25rem;
    }

    .eyebrow {
      margin: 0 0 0.35rem;
      color: var(--accent);
      font-size: 0.92rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .intro {
      max-width: 48rem;
      margin: 0.85rem 0 0;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.6;
    }

    .card {
      margin-top: 1.75rem;
      padding: clamp(1.25rem, 2vw, 2rem);
      border: 1px solid rgba(124, 142, 168, 0.22);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.88);
      box-shadow: var(--shadow);
      backdrop-filter: blur(10px);
    }

    .form-field {
      display: grid;
      gap: 1rem;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-inline-size: 0;
    }

    legend {
      padding: 0;
      font-size: 1.1rem;
      font-weight: 700;
      line-height: 1.35;
    }

    .required-mark {
      color: var(--accent);
    }

    .help-text {
      margin: 0.5rem 0 0;
      color: var(--muted);
      font-size: 0.97rem;
      line-height: 1.5;
    }

    .options {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      padding: 0.95rem 1rem;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface-alt);
      cursor: pointer;
      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
    }

    .radio-option:hover {
      border-color: var(--border-strong);
      background: #fff;
      transform: translateY(-1px);
    }

    .radio-option input {
      margin: 0;
      inline-size: 1.15rem;
      block-size: 1.15rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .radio-label {
      font-size: 1rem;
      font-weight: 600;
      line-height: 1.35;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      margin-top: 1.5rem;
    }

    .submit-button {
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.35rem;
      background: linear-gradient(135deg, #2563eb, #1d4ed8);
      color: #fff;
      font: inherit;
      font-weight: 700;
      letter-spacing: 0.01em;
      cursor: pointer;
      box-shadow: 0 10px 24px rgba(37, 99, 235, 0.28);
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    .submit-button:hover {
      transform: translateY(-1px);
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.32);
    }

    .submit-button:focus-visible,
    .radio-option input:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid #0f172a;
      outline-offset: 3px;
    }

    @media (max-width: 480px) {
      main {
        padding-inline: 0.75rem;
      }

      .actions {
        justify-content: stretch;
      }

      .submit-button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .card,
      .radio-option,
      .submit-button {
        forced-color-adjust: auto;
      }

      .radio-option,
      .submit-button {
        border: 1px solid CanvasText;
      }

      .submit-button {
        background: ButtonFace;
        color: ButtonText;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <div id="app"></div>

  <script>
    const notificationOptions = [
      { id: "notification-email", value: "email", label: "Email" },
      { id: "notification-sms", value: "sms", label: "SMS" },
      { id: "notification-push", value: "push", label: "Push Notifications" }
    ];

    const RadioOption = ({ id, value, label }) => `
      <label class="radio-option" for="${id}">
        <input id="${id}" name="notification-preference" type="radio" value="${value}" required>
        <span class="radio-label">${label}</span>
      </label>
    `;

    const NotificationPreferencesForm = () => `
      <main id="maincontent" tabindex="-1">
        <section class="page-shell" aria-labelledby="page-title">
          <div class="hero">
            <p class="eyebrow">Account settings</p>
            <h1 id="page-title">Notification preferences</h1>
            <p class="intro">
              Choose the single channel you want us to use for important updates.
            </p>
          </div>

          <form class="card" action="#" method="post">
            <div class="form-field">
              <fieldset aria-describedby="notification-help">
                <legend>
                  How do you prefer to receive notifications?
                  <span class="required-mark" aria-hidden="true"> *</span>
                </legend>
                <p class="help-text" id="notification-help">
                  Select one option. You can change this later in your account settings.
                </p>
                <div class="options">
                  ${notificationOptions.map(RadioOption).join("")}
                </div>
              </fieldset>
            </div>

            <div class="actions">
              <button class="submit-button" type="submit">Save preferences</button>
            </div>
          </form>
        </section>
      </main>
    `;

    document.getElementById("app").innerHTML = NotificationPreferencesForm();
  </script>
</body>
</html>
