     const notificationOptions = [
       { id: "notification-email", value: "email", label: "Email" },
       { id: "notification-sms", value: "sms", label: "SMS" },
       { id: "notification-push", value: "push", label: "Push Notifications" }
     ];

     const RadioOption = ({ id, value, label }) => `
       <label class="radio-option" for="${id}">
         <input id="${id}" name="notification-preference" type="radio" value="${value}" required>
         <span class="radio-label">${label}</span>
       </label>
     `;

     const NotificationPreferencesForm = () => `
       <main id="maincontent" tabindex="-1">
         <section class="page-shell" aria-labelledby="page-title">
           <div class="hero">
             <p class="eyebrow">Account settings</p>
             <h1 id="page-title">Notification preferences</h1>
             <p class="intro">
               Choose the single channel you want us to use for important updates.
             </p>
           </div>

           <form class="card" action="#" method="post">
             <div class="form-field">
               <fieldset aria-describedby="notification-help">
                 <legend>
                   How do you prefer to receive notifications?
                   <span class="required-mark" aria-hidden="true"> *</span>
                 </legend>
                 <p class="help-text" id="notification-help">
                   Select one option. You can change this later in your account settings.
                 </p>
                 <div class="options">
                   ${notificationOptions.map(RadioOption).join("")}
                 </div>
               </fieldset>
             </div>

             <div class="actions">
               <button class="submit-button" type="submit">Save preferences</button>
             </div>
           </form>
         </section>
       </main>
     `;

     document.getElementById("app").innerHTML = NotificationPreferencesForm();
   </script>
 </body>
